//! ASCII case folding and ASCII/IDN classification.
//!
//! Every routine here is deliberately byte-oriented: the C++ original operates
//! on `std::string`, which is a sequence of `char`, so case folding never
//! touches multi-byte UTF-8 sequences and `.size()` counts bytes.

/// Lowercases `A`..=`Z` and leaves every other byte untouched.
///
/// Bytes >= 0x80 are passed through verbatim, so `café` stays `café` and an
/// input that is not valid UTF-8 survives the round trip unchanged.
pub fn to_lower(input: &[u8]) -> Vec<u8> {
    input.iter().map(|b| b.to_ascii_lowercase()).collect()
}

/// Canonical form of a domain name.
///
/// The upstream library normalizes purely by case folding; it performs no
/// whitespace trimming, dot collapsing or Unicode normalization.
pub fn normalize(input: &[u8]) -> Vec<u8> {
    to_lower(input)
}

/// True when every byte is in the 7-bit ASCII range.
///
/// The empty string is vacuously ASCII, matching the C++ behaviour.
pub fn is_ascii_domain(input: &[u8]) -> bool {
    input.iter().all(|b| *b < 0x80)
}

/// True when at least one byte falls outside 7-bit ASCII.
pub fn is_idn_domain(input: &[u8]) -> bool {
    !is_ascii_domain(input)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lowercases_only_ascii_letters() {
        assert_eq!(to_lower(b"MiXeD.CaSe.CoM"), b"mixed.case.com".to_vec());
        assert_eq!(to_lower(b"1a-B_c"), b"1a-b_c".to_vec());
        // U+00C9 (0xC3 0x89) must survive byte-for-byte.
        assert_eq!(to_lower("\u{c9}".as_bytes()), "\u{c9}".as_bytes().to_vec());
    }

    #[test]
    fn normalize_matches_to_lower() {
        for probe in [&b"  spaced  "[..], b"a..b", b"A.", b"xn--ABC"] {
            assert_eq!(normalize(probe), to_lower(probe));
        }
    }

    #[test]
    fn classifies_ascii_and_idn() {
        assert!(is_ascii_domain(b""));
        assert!(is_ascii_domain(b"example.com"));
        assert!(is_ascii_domain(&[0x7f])); // DEL is still ASCII
        assert!(!is_ascii_domain(&[0xff]));
        assert!(is_idn_domain("\u{65e5}".as_bytes()));
        assert!(!is_idn_domain(b"example.com"));
    }
}

