//! Length validation and label counting.
//!
//! Both limits are measured in bytes, mirroring `std::string::size()`: a label
//! of 21 CJK characters (63 bytes) is accepted while 22 (66 bytes) is not.

/// Maximum byte length accepted by [`is_valid_domain`].
pub const MAX_DOMAIN_LEN: usize = 255;

/// Maximum byte length accepted by [`is_valid_label`].
pub const MAX_LABEL_LEN: usize = 63;

/// The label separator.
pub const LABEL_SEPARATOR: u8 = b'.';

/// True when the input is a non-empty byte string of at most 255 bytes.
///
/// Only the overall length is checked: individual label lengths and the
/// character repertoire are not inspected, so `"a"` repeated 64 times and
/// `"under_score"` are both accepted.
pub fn is_valid_domain(input: &[u8]) -> bool {
    !input.is_empty() && input.len() <= MAX_DOMAIN_LEN
}

/// True when the input is a non-empty byte string of at most 63 bytes.
///
/// Embedded separators are not rejected, so `"a.b"` counts as a valid label.
pub fn is_valid_label(input: &[u8]) -> bool {
    !input.is_empty() && input.len() <= MAX_LABEL_LEN
}

/// Number of separator-delimited labels: one more than the number of dots.
///
/// Empty labels are counted, so `""` yields 1, `"."` yields 2 and `"a..b"`
/// yields 3.
pub fn count_labels(input: &[u8]) -> usize {
    input.iter().filter(|b| **b == LABEL_SEPARATOR).count() + 1
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn domain_length_bounds() {
        assert!(!is_valid_domain(b""));
        assert!(is_valid_domain(b"a"));
        assert!(is_valid_domain(&vec![b'a'; MAX_DOMAIN_LEN]));
        assert!(!is_valid_domain(&vec![b'a'; MAX_DOMAIN_LEN + 1]));
        // Long labels do not invalidate the domain.
        assert!(is_valid_domain(&vec![b'a'; 64]));
    }

    #[test]
    fn label_length_bounds() {
        assert!(!is_valid_label(b""));
        assert!(is_valid_label(&vec![b'a'; MAX_LABEL_LEN]));
        assert!(!is_valid_label(&vec![b'a'; MAX_LABEL_LEN + 1]));
        assert!(is_valid_label(b"a.b"));
    }

    #[test]
    fn lengths_are_measured_in_bytes() {
        let twenty_one = "\u{65e5}".repeat(21); // 63 bytes
        let twenty_two = "\u{65e5}".repeat(22); // 66 bytes
        assert!(is_valid_label(twenty_one.as_bytes()));
        assert!(!is_valid_label(twenty_two.as_bytes()));

        let eighty_five = "\u{65e5}".repeat(85); // 255 bytes
        let eighty_six = "\u{65e5}".repeat(86); // 258 bytes
        assert!(is_valid_domain(eighty_five.as_bytes()));
        assert!(!is_valid_domain(eighty_six.as_bytes()));
    }

    #[test]
    fn counts_labels() {
        assert_eq!(count_labels(b""), 1);
        assert_eq!(count_labels(b"one"), 1);
        assert_eq!(count_labels(b"two.three"), 2);
        assert_eq!(count_labels(b"four.five.six"), 3);
        assert_eq!(count_labels(b"."), 2);
        assert_eq!(count_labels(b"a..b"), 3);
    }
}

