//! Command-line argument access that preserves the raw bytes the OS handed us.
//!
//! The C++ program receives `char*` arguments and echoes them straight to
//! `std::cout`, so an argument that is not valid UTF-8 is reproduced verbatim.
//! `std::env::args()` would panic on such input; iterating the `OsString` form
//! and borrowing its bytes keeps the Rust port byte-for-byte faithful.

use std::env;

/// Returns the positional arguments after the program name, as raw bytes.
pub fn positional_args() -> Vec<Vec<u8>> {
    env::args_os().skip(1).map(|arg| into_bytes(&arg)).collect()
}

#[cfg(unix)]
fn into_bytes(arg: &std::ffi::OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    arg.as_os_str().as_bytes().to_vec()
}

#[cfg(not(unix))]
fn into_bytes(arg: &std::ffi::OsString) -> Vec<u8> {
    // Non-Unix targets have no lossless byte view of an OsString; UTF-8 is the
    // only representation available there.
    arg.to_string_lossy().into_owned().into_bytes()
}

