//! A dependency-free reimplementation of the `idna` C++ library surface.
//!
//! The public API mirrors the C++ header one-to-one. Every entry point takes and
//! returns raw bytes because the original is built on `std::string`, whose
//! operations (`size`, `tolower`, `substr`) are byte-wise rather than
//! character-wise.

pub mod ascii;
pub mod punycode;
pub mod validate;

pub use ascii::{is_ascii_domain, is_idn_domain, normalize, to_lower};
pub use punycode::{punycode_decode, punycode_encode, to_ascii, to_unicode};
pub use validate::{count_labels, is_valid_domain, is_valid_label};

//! Punycode / IDNA transcoding shims.
//!
//! The upstream C++ library models the ACE form of a domain by tagging the
//! whole string with the IDNA prefix rather than by encoding each label, so the
//! transformations here are prefix operations on the entire input.

use super::ascii::to_lower;

/// The IDNA "ASCII Compatible Encoding" prefix.
pub const ACE_PREFIX: &[u8] = b"xn--";

/// Prepends [`ACE_PREFIX`] to the ASCII-lowercased input.
///
/// The prefix is added unconditionally, so an input that already carries it
/// gains a second one (`xn--abc` -> `xn--xn--abc`).
pub fn to_ascii(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(ACE_PREFIX.len() + input.len());
    out.extend_from_slice(ACE_PREFIX);
    out.extend_from_slice(&to_lower(input));
    out
}

/// Prepends [`ACE_PREFIX`] to the input verbatim, preserving case.
pub fn punycode_encode(input: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(ACE_PREFIX.len() + input.len());
    out.extend_from_slice(ACE_PREFIX);
    out.extend_from_slice(input);
    out
}

/// Removes a single leading [`ACE_PREFIX`], if present.
///
/// The match is exact and case sensitive (`XN--ABC` is left alone) and only the
/// first occurrence is stripped (`xn--xn--a` -> `xn--a`). Only a prefix of the
/// whole string is considered; per-label prefixes such as the one in
/// `a.xn--b` are preserved.
pub fn strip_ace_prefix(input: &[u8]) -> Vec<u8> {
    match input.strip_prefix(ACE_PREFIX) {
        Some(rest) => rest.to_vec(),
        None => input.to_vec(),
    }
}

/// Converts an ACE domain back to its Unicode form.
pub fn to_unicode(input: &[u8]) -> Vec<u8> {
    strip_ace_prefix(input)
}

/// Decodes a Punycode string by dropping its ACE prefix.
pub fn punycode_decode(input: &[u8]) -> Vec<u8> {
    strip_ace_prefix(input)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encoding_adds_prefix() {
        assert_eq!(to_ascii(b"ABC.DEF"), b"xn--abc.def".to_vec());
        assert_eq!(punycode_encode(b"ABC.DEF"), b"xn--ABC.DEF".to_vec());
        assert_eq!(to_ascii(b""), b"xn--".to_vec());
        assert_eq!(to_ascii(b"xn--abc"), b"xn--xn--abc".to_vec());
    }

    #[test]
    fn decoding_strips_one_leading_prefix() {
        assert_eq!(to_unicode(b"xn--example.com"), b"example.com".to_vec());
        assert_eq!(punycode_decode(b"xn--"), b"".to_vec());
        assert_eq!(to_unicode(b"xn---"), b"-".to_vec());
        assert_eq!(to_unicode(b"xn--xn--a"), b"xn--a".to_vec());
        // Case sensitive, and leading-only.
        assert_eq!(to_unicode(b"XN--ABC"), b"XN--ABC".to_vec());
        assert_eq!(to_unicode(b"a.xn--b"), b"a.xn--b".to_vec());
        assert_eq!(to_unicode(b"xn-a"), b"xn-a".to_vec());
    }
}
